import itertools

def solve_small(n):
    # Generate all tilings of an n x n board
    # Using a backtracking approach
    board_size = n * n
    cells = [(i, j) for i in range(n) for j in range(n)]

    def get_tilings(occupied):
        if len(occupied) == board_size:
            return [[]]

        # Find first unoccupied cell
        first = 0
        while first < board_size and cells[first] in occupied:
            first += 1

        if first == board_size:
            return [[]]

        r, c = cells[first]
        res = []
        # Try horizontal
        if c + 1 < n and (r, c + 1) not in occupied:
            for t in get_tilings(occupied | {cells[first], (r, c + 1)}):
                res.append([(cells[first], (r, c + 1))] + t)
        # Try vertical
        if r + 1 < n and (r + 1, c) not in occupied:
            for t in get_tilings(occupied | {cells[first], (r + 1, c)}):
                res.append([(cells[first], (r + 1, c))] + t)
        return res

    tilings = get_tilings(set())
    num_tilings = len(tilings)
    print(f"n={n}, num_tilings={num_tilings}")

    # For each subset of cells, check if it satisfies the condition
    # k is the size of the subset
    min_k = float('inf')
    for k in range(1, board_size + 1):
        for S in itertools.combinations(cells, k):
            # S is a set of marked cells
            # Check how many tilings are "valid" (no domino has 2 marked cells)
            valid_tilings = []
            for T in tilings:
                is_valid = True
                for d in T:
                    # d is (cell1, cell2)
                    count = 0
                    if d[0] in S: count += 1
                    if d[1] in S: count += 1
                    if count == 2:
                        is_valid = False
                        break
                if is_valid:
                    valid_tilings.append(T)

            if len(valid_tilings) == 1:
                return k
    return None

