def solve_small_optimized(n):
    import itertools

    def get_tilings(n):
        board_size = n * n
        cells = [(i, j) for i in range(n) for j in range(n)]

        def backtrack(occupied):
            if len(occupied) == board_size:
                return [[]]

            idx = 0
            while idx < board_size and cells[idx] in occupied:
                idx += 1

            if idx == board_size:
                return [[]]

            r, c = cells[idx]
            res = []
            # Try horizontal
            if c + 1 < n and (r, c + 1) not in occupied:
                for t in backtrack(occupied | {cells[idx], (r, c + 1)}):
                    res.append((cells[idx], (r, c + 1), t))
            # Try vertical
            if r + 1 < n and (r + 1, c) not in occupied:
                for t in backtrack(occupied | {cells[idx], (r + 1, c)}):
                    res.append((cells[idx], (r + 1, c), t))
            return res

        raw_tilings = backtrack(set())
        # raw_tilings is a list of tuples, each tuple is (d1, d2, ..., dn^2/2)
        # but it's actually nested. Let's fix that.
        tilings = []
        def flatten(t):
            if not t: return []
            d = t[0]
            return [d] + flatten(t[1:])

        for rt in raw_tilings:
            tilings.append(flatten(rt))
        return tilings

    tilings = get_tilings(n)
    board_size = n * n
    cells = [(i, j) for i in range(n) for j in range(n)]

    for k in range(1, board_size + 1):
        for S in itertools.combinations(cells, k):
            S_set = set(S)
            valid_tilings_count = 0
            for T in tilings:
                is_valid = True
                for d in T:
                    if d[0] in S_set and d[1] in S_set:
                        is_valid = False
                        break
                if is_valid:
                    valid_tilings_count += 1
                    if valid_tilings_count > 1:
                        break
            if valid_tilings_count == 1:
                return k
    return None

